// Tier names and points, COMMON first.
const RARE_TIERS = [
  { id: "common", name: "COMMON", pts: 10 },
  { id: "uncommon", name: "UNCOMMON", pts: 25 },
  { id: "rare", name: "RARE", pts: 45 },
  { id: "epic", name: "EPIC", pts: 70 },
  { id: "legend", name: "LEGENDARY", pts: 100 },
];

// Parsed: [{ q, tiers: [[{ name, keys: [normalised spellings] }, ...] x5] }]
const RARE_PROMPTS = RARE_RAW.map((line) => {
  // split on the first "#" only, so answers like "c#" survive
  const cut = line.indexOf("#");
  const q = line.slice(0, cut), body = line.slice(cut + 1);
  const seen = new Set();
  const raw = body.split(";");
  // a prompt written with four tiers: the first third of the last one is EPIC, the rest LEGENDARY
  if (raw.length === 4) {
    const last = raw[3].split(",");
    const k = Math.max(3, Math.round(last.length * 0.33));
    raw.splice(3, 1, last.slice(0, k).join(","), last.slice(k).join(","));
  }
  const tiers = raw.map((t) => t.split(",").map((a) => a.trim()).filter(Boolean).map((a) => {
    const spell = a.split("|").map((s) => s.trim());
    return { name: spell[0], keys: spell.map(rareNorm) };
  }).filter((a) => {
    // an answer listed twice keeps its most common tier
    if (a.keys.some((k) => seen.has(k))) return false;
    a.keys.forEach((k) => seen.add(k));
    return true;
  }));
  return { q, tiers };
});

// Normalise an answer for matching: lower case, no accents, no punctuation or spaces,
// no leading "the", and plurals folded to their singular.
function rareNorm(s) {
  let t = String(s).toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "")
    .replace(/&/g, " and ").replace(/\+/g, "plus").replace(/#/g, "sharp").replace(/^\s*(the|a|an)\s+/, "").replace(/[^a-z0-9]/g, "");
  if (t.length > 4) {
    if (t.endsWith("ies")) t = t.slice(0, -3) + "y";
    else if (/(ches|shes|xes|oes|sses)$/.test(t)) t = t.slice(0, -2);
    else if (t.endsWith("s") && !t.endsWith("ss") && !t.endsWith("us") && !t.endsWith("is")) t = t.slice(0, -1);
  }
  return t;
}
